# What if the output has a checkerboard pattern in the fill regions?

def create_checkerboard_fill(input_grid):
    height = len(input_grid)
    width = len(input_grid[0])
    output = []

    # First identify divider rows and columns
    divider_rows = []
    divider_cols = []

    for i in range(height):
        # Row is a divider if it has 4 in it (intersection)
        # or if it's predominantly value other than 5 (it's a divider)
        if i in [0, 27]:  # Known divider rows
            divider_rows.append(i)

    for j in range(width):
        # Check if column j has 4s in any row (known to be col 4 and 24)
        if j in [4, 24]:
            divider_cols.append(j)

    # Create output with checkerboard in fill regions
    for i in range(height):
        row = []
        for j in range(width):
            # Check if this cell is in a divider row or divider col
            is_in_divider_row = i in divider_rows or j in divider_cols

            if is_in_divider_row:
                # Divider region: depends on whether it's row or column
                if i == 0 or j == 0:
                    # Top-left corner handling
                    if i in divider_rows:
                        # Check original value
                        pass
                    else:
                        row.append(4)  # Assume intersections get 4
