def create_checkerboard(input_grid):
    height = len(input_grid)
    width = len(input_grid[0])
    output = []

    divider_rows = [0, 27]
    divider_cols = [4, 24]

    for i in range(height):
        row = []
        for j in range(width):
            is_div_row = i in divider_rows
            is_div_col = j in divider_cols

            if is_div_row or is_div_col:
