                    row.append(4)
                elif is_div_row:
                    row.append(7)
                else:
                    row.append(7)
            else:
                # Checkerboard: different value based on position
                if (i + j) % 2 == 0:
                    row.append(5)
                else:
                    row.append(7)  # Alternate with 7
        output.append(row)

